fun main() {
    println(1.0)
    println(1.5f)
    println(100.0 / 3)
    println(1e10)
    println(1.0E-5)
    println(123456789.0)
    println(1234567890123.0)
    println(0.1f + 0.2f)
    println(3.0f * 1.1f)
    println(Double.MAX_VALUE)
    println(Float.MIN_VALUE)
    println(2.0.pow2())
    println(Math.sqrt(2.0))
    println(Math.pow(2.0, 10.0))
    println(Math.round(2.5) to Math.round(-2.5) to Math.round(3.49))
    println(Math.floor(-1.5) to Math.ceil(-1.5))
    println(Math.abs(-3.5) + Math.max(1.0, 2.0))
    println(kotlin.math.abs(-4) + kotlin.math.max(3, 9))
    println(kotlin.math.sign(-2.0))
    println(5.toDouble() / 2)
    println(7.0.toInt() / 2)
    println(1.23456789.toFloat())
    println("3.5".toDouble() + "2".toInt())
    println("1e3".toDouble())
    println("abc".toDoubleOrNull())
    println(10.0.toString() + 10f)
    println((0.1 + 0.7) * 10)
    println(1.0 / 3 * 3 == 1.0)
    println(Double.NaN.isNaN() to (1.0 / 0).isInfinite())
    println(12345.6789.toLong())
    println(kotlin.math.round(2.567 * 100) / 100)
    println(Math.hypot(3.0, 4.0))
    println(Math.log(Math.E) + Math.exp(0.0))
    println(Math.sin(0.0) + Math.cos(0.0))
    println(Math.toDegrees(Math.PI))
    println(16.0.let { kotlin.math.sqrt(it).toInt() })
    println(-0.0 == 0.0)
    println(0.0.equals(-0.0))
    println(minOf(1.5, 0.5))
    println(7.5.rem(2.0) to (-7.5) % 2)
    println(Long.MAX_VALUE / 2.0)
}

fun Double.pow2() = this * this
